"""Tests for check_excerpts.py. Run: python3 -m unittest discover -s .github/scripts/dart-docs -p 'test_*.py'"""

import os
import subprocess
import sys
import tempfile
import unittest

SCRIPT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "check_excerpts.py")

GENERATED = """\
// Generated by forge. Do not edit.

/// `GET /orders/{id}`
final getOrder = query<Order, GetOrderArgs>(opGetOrder, Order.fromClient);

final class GetOrderArgs implements OperationArgs {
  const GetOrderArgs({
    required this.id,
  });

  final String id;
}
"""


def write(path, text):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        f.write(text)


class CheckExcerptsTest(unittest.TestCase):
    def setUp(self):
        self.docs = tempfile.mkdtemp()
        self.orders = tempfile.mkdtemp()
        self.other = tempfile.mkdtemp()
        write(os.path.join(self.orders, "lib/src/bindings/get_order.dart"), GENERATED)

    def run_script(self, body, *clients):
        write(os.path.join(self.docs, "page.mdx"), "---\ntitle: P\n---\n\n" + body)
        clients = clients or (self.other, self.orders)
        return subprocess.run([sys.executable, SCRIPT, self.docs, *clients], capture_output=True, text=True)

    def test_an_excerpt_that_leaves_lines_out_passes(self):
        result = self.run_script(
            '```dart title="lib/src/bindings/get_order.dart"\n'
            "/// `GET /orders/{id}`\n"
            "final getOrder = query<Order, GetOrderArgs>(opGetOrder, Order.fromClient);\n"
            "\n"
            "final class GetOrderArgs implements OperationArgs {\n"
            "  // fields elided\n"
            "  final String id;\n"
            "}\n"
            "```\n"
        )
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertIn("1 generated excerpts match", result.stdout)

    def test_whitespace_does_not_matter(self):
        result = self.run_script(
            '```dart title="lib/src/bindings/get_order.dart"\n'
            "final   getOrder =\tquery<Order, GetOrderArgs>(opGetOrder, Order.fromClient);\n"
            "```\n"
        )
        self.assertEqual(result.returncode, 0, result.stderr)

    def test_a_changed_line_fails_and_names_it(self):
        result = self.run_script(
            '```dart title="lib/src/bindings/get_order.dart"\n'
            "final getOrder = query<Order, GetOrderArgs>(opGetOrder, Order.fromWire);\n"
            "```\n"
        )
        self.assertEqual(result.returncode, 1)
        self.assertIn("Order.fromWire", result.stderr)
        self.assertIn("page.mdx, block 1", result.stderr)

    def test_lines_in_a_different_order_pass(self):
        result = self.run_script(
            '```dart title="lib/src/bindings/get_order.dart"\n'
            "final class GetOrderArgs implements OperationArgs {\n"
            "final getOrder = query<Order, GetOrderArgs>(opGetOrder, Order.fromClient);\n"
            "```\n"
        )
        self.assertEqual(result.returncode, 0, result.stderr)

    def test_a_glob_title_draws_from_every_file_it_matches(self):
        write(os.path.join(self.orders, "lib/src/bindings/list_orders.dart"), "// Generated by forge.\nfinal listOrders = query<OrderPage, NoArgs>(opListOrders, OrderPage.fromClient);\n")
        ok = self.run_script(
            '```dart title="lib/src/bindings/*.dart"\n'
            "final getOrder = query<Order, GetOrderArgs>(opGetOrder, Order.fromClient);\n"
            "final listOrders = query<OrderPage, NoArgs>(opListOrders, OrderPage.fromClient);\n"
            "```\n"
        )
        self.assertEqual(ok.returncode, 0, ok.stderr)
        bad = self.run_script(
            '```dart title="lib/src/bindings/*.dart"\n'
            "final listOrders = query<OrderPage, NoArgs>(opListOrders, OrderPage.fromJson);\n"
            "```\n"
        )
        self.assertEqual(bad.returncode, 1)

    def test_a_doc_comment_is_checked_but_a_plain_comment_is_not(self):
        wrong_doc = self.run_script(
            '```dart title="lib/src/bindings/get_order.dart"\n'
            "/// `GET /orders`\n"
            "```\n"
        )
        self.assertEqual(wrong_doc.returncode, 1)
        plain = self.run_script(
            '```dart title="lib/src/bindings/get_order.dart"\n'
            "// anything the author likes\n"
            "```\n"
        )
        self.assertEqual(plain.returncode, 0, plain.stderr)

    def test_a_file_no_client_has_fails(self):
        result = self.run_script(
            '```dart title="lib/src/bindings/nope.dart"\n'
            "final x = 1;\n"
            "```\n"
        )
        self.assertEqual(result.returncode, 1)
        self.assertIn("no generated file matches that title", result.stderr)

    def test_any_client_carrying_the_lines_is_enough(self):
        write(os.path.join(self.other, "lib/src/bindings/get_order.dart"), "// Generated by forge.\nfinal other = 1;\n")
        result = self.run_script(
            '```dart title="lib/src/bindings/get_order.dart"\n'
            "final getOrder = query<Order, GetOrderArgs>(opGetOrder, Order.fromClient);\n"
            "```\n"
        )
        self.assertEqual(result.returncode, 0, result.stderr)

    def test_the_report_names_the_line_missing_from_the_closest_client(self):
        # self.other comes first and has the file but none of the lines; self.orders
        # has all but one. The report must name the line the closest client lacks.
        write(os.path.join(self.other, "lib/src/bindings/get_order.dart"), "// Generated by forge.\nfinal other = 1;\n")
        result = self.run_script(
            '```dart title="lib/src/bindings/get_order.dart"\n'
            "final getOrder = query<Order, GetOrderArgs>(opGetOrder, Order.fromClient);\n"
            "final getOrderTwo = query<Order, GetOrderArgs>(opGetOrder, Order.fromWire);\n"
            "```\n"
        )
        self.assertEqual(result.returncode, 1)
        self.assertIn("Order.fromWire", result.stderr)
        self.assertNotIn("final getOrder = query<Order, GetOrderArgs>(opGetOrder, Order.fromClient);'", result.stderr)

    def test_untitled_blocks_are_ignored(self):
        result = self.run_script("```dart\nfinal anything = 1;\n```\n")
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertIn("0 generated excerpts", result.stdout)

    def test_missing_arguments_is_a_usage_error(self):
        result = subprocess.run([sys.executable, SCRIPT, self.docs], capture_output=True, text=True)
        self.assertEqual(result.returncode, 2)


if __name__ == "__main__":
    unittest.main()
